pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        Reverter r = new Reverter();
        vm.prank(owner);
        c = new C();
        // owner is the initial owner; transfer ownership via deploy with different msg.sender doesn't work directly.
        // Instead, we set up a scenario where the owner is the Reverter contract.
        // We deploy a new C where msg.sender is the Reverter.
        vm.prank(address(r));
        C c2 = new C();
        // fund the contract
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool sent,) = address(c2).call{value: 1 ether}("");
        require(sent);
        // now withdrawAll as the owner (reverter)
        vm.prank(address(r));
        c2.withdrawAll();
        // After withdrawAll, the contract's balance must be zero in the correct version.
        // In the buggy version, sendMoney to the Reverter fails, leaving balance.
        assertTrue(address(c2).balance == 0);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

